//run studio mdl
function compileMDL_OnClicked(filename)
{
	shell = new ActiveXObject("WScript.Shell");
	old_path = SMDfolder.value;
	mdl_path = old_path.replace("content","game");
	slash = '\\';
//studio MDL spits out a bunch of model names so we need to check all of them 
//and see if they need to be checked out
	mdl_filetype = new Array (".dx80.vtx", ".dx90.vtx", ".mdl", ".phy",".sw.vtx", ".vvd", ".xbox.vtx");
	files = new Array;
	for (i = 0; i < mdl_filetype.length; i++)
		{
			filename = mdl_path + slash + mdl_name.value + mdl_filetype[i];
			fso = new ActiveXObject("Scripting.FileSystemObject");
			if (fso.FileExists(filename))
			{
			//		first see if the file needs to be checked out
			//		before exporting check if file is checked out
			file = fso.GetFile(filename);
			readonly =file.attributes & 1;
			if (readonly == 1)
				{
				//XSI won't allow me to write clean code so this big chunck of stuff is being inserted instead of trying
				//to call a function
					var checkExist = ActiveSceneRoot.Properties("Checkout");
					if(checkExist)
					{
					logmessage ("Deleting Checkout Property");
					DeleteObj(checkExist);
					} 
				//create ppg
				var oPpg = ActiveSceneRoot.AddProperty("CustomProperty",false,"Checkout");
				var chklayout = oPpg.PPGlayout;
				//store filename here
				oPpg.AddParameter3("file_name", siString, filename);

				chklayout.addGroup();
					chklayout.addRow();
							chklayout.Additem ("file_name", "File:", siControlString);
					chklayout.endRow();
	
				chklayout.endGroup();

				chklayout.Language = "JScript";
				
				checkoutfile = InspectObj(oPpg, "", "Check Out File", 4,false);
				if (!checkoutfile)
				{	
					vstcheckoutfile(filename);
		
				}		
				else
				{
					logmessage ("user cancelled");
				}	
			}
			}
		}
	vproject = XSIUtils.Environment("VProject");
	studiomdl_path = vproject.split("game");
	qc = ".qc";
	qc_name = mdl_name.value + qc;
	shell = new ActiveXObject("WScript.Shell");
	fso = new ActiveXObject("Scripting.FileSystemObject");
	exists = fso.FileExists(qc_name)
	if (!exists)
	{
		logmessage ("Can't find the QC file: " + qc_name, siFatal);
		return;
	}
	path = SMDfolder.value;
	slash = '/';
	qc_file = path + slash + qc_name;
	studiomdl = (studiomdl_path[0] + "game/bin/studiomdl " + qc_file);
	logmessage (studiomdl);
	shell.Run(studiomdl);
}


//open MDL
function openMDL_OnClicked()
{
	mdl= ".mdl";
	mdlname = mdl_name.value + mdl;
	shell = new ActiveXObject("WScript.Shell");
	old_path = SMDfolder.value;
	mdl_path = old_path.replace("content","game");
	slash = '/';
	mdl_file = mdl_path + slash + mdlname;
	//see if it exists first
	fso = new ActiveXObject("Scripting.FileSystemObject");
	exists = fso.FileExists(mdl_file)
	if (exists)
	{
	shell.Run(mdl_file);
	}
	else
		{
		logmessage ("MDL does not exist", siFatal)
		}
}	

